import {SCENARIOS} from './scenarios.js?release=20261016-single-page4';
import {applyHardwareAction,verifyHardware,renderHardware} from './hardware.js?release=20261016-single-page4';
import {applyWorkspaceAction,verifyWorkspace,renderWorkspace} from './workspaces.js?release=20261016-single-page4';
import {classroomStorageKey,attachClassroomLab} from './classroom-client.js?release=20261016-single-page4';
import {normalizeLabRecord} from './records.js?release=20261016-single-page4';
import {privacyPage} from './privacy.js?release=20261016-single-page4';
import {createWorkStorage,CLEAR_WORK_KEY,WORK_PREFIX,hasPrivateWork} from './local-work.js?release=20261016-single-page4';
import {mountWorkControls,workStatus} from './work-controls.js?release=20261016-single-page4';

const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageKey=classroomStorageKey();
const tracks={hardware:{name:'Hardware & ServiceDesk',short:'Hardware',symbol:'◈',color:'teal',description:'Work the bench. Trace symptoms, inspect components, and bring a computer back to life.'},network:{name:'Networking & operating systems',short:'Networks & OS',symbol:'⌘',color:'blue',description:'Follow the connection. Work with addresses, permissions, networks, and system services.'},ai:{name:'AI literacy & audit',short:'AI & ethics',symbol:'✳',color:'violet',description:'Question the output. Protect privacy, check evidence, and examine the code.'},security:{name:'Ethical cybersecurity',short:'Cybersecurity',symbol:'◇',color:'amber',description:'Investigate responsibly. Triage an incident, reduce access, and patch a simulated weakness.'}};
let store={version:2,labs:{}};
let storageAvailable=true;
let deviceStorage;try{deviceStorage=localStorage;}catch{storageAvailable=false;}
let workStorage=createWorkStorage({storage:deviceStorage,key:storageKey,scenarios:SCENARIOS});
let classroomSharingPaused=false;
let reportCleanup=null;
let currentLab=null,libraryTrack='all',libraryGrade='all',libraryQuery='',noticeTimer,classroomConnection=null;
function save(){storageAvailable=workStorage.save(store);if(!storageAvailable)showNotice('Device saving is unavailable. Export your private work before leaving.');classroomConnection?.schedule();}
function resetLocalSession(){workStorage.pause();classroomConnection?.dispose();classroomConnection=null;classroomSharingPaused=true;storageKey=WORK_PREFIX;workStorage=createWorkStorage({storage:deviceStorage,key:storageKey,scenarios:SCENARIOS});store={version:2,labs:{}};renderRoute();}
function bindWorkPrivacy(s){mountWorkControls({host:$('#work-privacy'),manager:workStorage,getStore:()=>store,scenarioId:s.id,replaceStore:value=>{store=value;renderRoute();},onClear:cleared=>{resetLocalSession();showNotice(cleared?'Local lab data cleared. Downloads and previously submitted records are separate.':'This page’s work is cleared, but device deletion could not be confirmed. Clear this site’s data in browser settings before sharing the profile.');},onChange:()=>{bindWorkPrivacy(s);const status=$('.save-status');if(status)status.textContent=workStatus(recordFor(s),workStorage);}});}
window.addEventListener('storage',event=>{if(event.key===CLEAR_WORK_KEY&&event.newValue){resetLocalSession();showNotice('Local lab data was cleared in another tab. This page has stopped saving and sharing.');}});
window.addEventListener('pagehide',()=>{reportCleanup?.();reportCleanup=null;classroomConnection?.dispose();if(!workStorage.persistent){store={version:2,labs:{}};$('#main')?.replaceChildren();}});
window.addEventListener('pageshow',event=>{if(event.persisted)renderRoute();});
window.addEventListener('beforeunload',event=>{if(!workStorage.persistent&&Object.values(store.labs).some(hasPrivateWork)){event.preventDefault();event.returnValue='';}});
function showNotice(message){const n=$('#notice');n.textContent=message;n.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>{n.hidden=true;},5000);}
function recordFor(scenario){const existing=Object.hasOwn(store.labs,scenario.id)?store.labs[scenario.id]:null;return store.labs[scenario.id]=normalizeLabRecord(scenario,existing);}
function countComplete(){return SCENARIOS.filter(s=>store.labs[s.id]?.closed===true).length;}
function routeLink(route,text,style='button'){return `<a class="${style}" href="#${route}">${text}</a>`;}
function tag(text,extra=''){return `<span class="tag ${extra}">${text}</span>`;}
function sectionHead(eyebrow,title,description=''){return `<div class="section-heading"><p class="eyebrow">${eyebrow}</p><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>`;}
function stationArt(){return `<div class="station-art" aria-hidden="true"><div class="station-floor"></div><div class="station-monitor"><div class="station-screen"><div class="screen-menu"><i></i><i></i><i></i><span>CLASSROOM DESKTOP · HDMI</span></div><div class="screen-signal"><span class="signal-icon">⌁</span><b>No signal</b><small>Check the video cable and input source.</small></div><div class="screen-bottom"><span>Power on</span><span>●</span></div></div><div class="monitor-logo">COLE / LAB 01</div></div><div class="station-stand"></div><div class="station-base"></div><div class="station-tower"><div class="tower-top"></div><div class="tower-front"><i class="power-led"></i><div class="tower-ports">▰<br>▰<br>●</div><div class="tower-vent"></div><span>WORKSTATION 01</span></div><div class="tower-side"><div class="board-traces"></div><div class="hero-fan"><i></i><i></i><i></i><i></i></div><div class="hero-ram"></div><div class="hero-gpu">GRAPHICS</div><div class="hero-ssd">SATA / SSD</div><div class="hero-wire"></div></div></div><div class="station-keyboard"></div><div class="station-cable"></div><span class="part-callout callout-one">01 / FOLLOW THE SIGNAL</span><span class="part-callout callout-two">02 / INSPECT THE HARDWARE</span></div>`;}

function home(){return `<section class="home-hero"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> ALAN “AL” COLE · Mx. COLE</p><h1>Technology should<br><em>make sense.</em></h1><p class="hero-description">I support K–12 technology and build projects that bring together defensive security, responsible AI, and hands-on learning.</p><p class="hero-subtext">Explore my work. Then pull up a chair at the virtual bench.</p><div class="button-row">${routeLink('labs','Explore the virtual labs <span aria-hidden="true">↗</span>')}${routeLink('projects','See my work <span aria-hidden="true">→</span>','button button-outline')}</div><div class="hero-credentials"><span>K–12 IT support</span><span>Cybersecurity at UAlbany</span><span>Future CTE educator</span></div></div><div class="hero-lab-preview"><div class="preview-topline"><span><i class="status-dot"></i> INSIDE THE VIRTUAL LAB</span><span>SIMULATED ENVIRONMENT</span></div>${stationArt()}<a class="preview-ticket" href="#lab/INC-101"><span class="ticket-letter">A</span><span><small>INC-101 / HARDWARE & SERVICEDESK</small><strong>The Blank Monitor</strong></span><span aria-hidden="true">↗</span></a></div></section>
<section class="fact-strip" aria-label="Learning platform at a glance"><div><b>15</b><span>interactive investigations</span></div><div><b>4</b><span>technology pathways</span></div><div><b>7–12</b><span>grade-level starting points</span></div><p>Ask questions. Gather evidence.<br><strong>Understand why the solution works.</strong></p></section>
<section class="section wrap">${sectionHead('WORK WITH PURPOSE','Security, learning, and the people in between.','My projects explore how technology can protect people, explain its decisions, and make room for curiosity.')}<div class="project-feature"><div class="guardian-visual" aria-hidden="true"><div class="browser-chrome"><i></i><i></i><i></i><span>AI Guardian / Web Shield</span></div><div class="guardian-card"><span class="guard-shield">✓</span><small>PAUSE. UNDERSTAND. DECIDE.</small><h3>A clearer view<br>of online risk.</h3><div class="risk-line"><span>Link signals</span><b>Review</b></div><div class="risk-line"><span>Analysis location</span><b>On device</b></div><p>Illustration of the project’s design focus.</p></div></div><div class="project-copy"><p class="eyebrow">FEATURED PROJECT / BROWSER SECURITY</p><h3>AI Guardian Web Shield</h3><p>A privacy-conscious browser-security project that turns locally available page and link signals into plain-language risk guidance.</p><p>It connects the technical work of recognizing suspicious patterns with the human work of making informed decisions.</p><div class="button-row">${routeLink('projects','Explore my projects →','text-link')}<a class="text-link" href="https://chromewebstore.google.com/detail/ai-guardian-web-shield/ipledehmklfhhdpobeogfdhmhdhmnden" target="_blank" rel="noopener noreferrer">Chrome Web Store ↗</a></div></div></div></section>
<section class="pathway-section"><div class="wrap section">${sectionHead('COLE LEARNING LABS','A place to work the problem.','Virtual workspaces for real problem-solving habits. Pick a pathway, investigate a ticket, and show your reasoning.')}<div class="pathway-grid">${Object.entries(tracks).map(([id,t])=>`<a class="pathway-card ${t.color}" href="#labs/${id}"><span class="pathway-symbol">${t.symbol}</span><span class="eyebrow">${id==='hardware'?'06':'03'} INVESTIGATIONS</span><h3>${t.name}</h3><p>${t.description}</p><span class="text-link">Open pathway <span aria-hidden="true">↗</span></span></a>`).join('')}</div></div></section>
<section class="wrap section teaching-intro"><div><p class="eyebrow">FOR THE CLASSROOM</p><h2>The thinking matters<br>as much as the fix.</h2></div><div><p>These labs are built around a repeatable process: understand the request, gather evidence, make a plan, test carefully, and verify the original task.</p><p>Use them for a whole-class demonstration, guided investigation, independent practice, or a discussion about responsible technology.</p>${routeLink('educators','Plan a lesson →','button button-outline')}</div></section>`;}

function projectPage(){return `<section class="page-intro wrap"><p class="eyebrow">PROJECT PORTFOLIO</p><h1>Ideas put<br><em>to work.</em></h1><p>Projects connecting practical IT support with defensive security, responsible AI, and technology education.</p></section><section class="wrap project-list">${[
{n:'01',name:'AI Guardian Web Shield',type:'BROWSER SECURITY · PUBLISHED EXTENSION',text:'People need understandable guidance when a page or link looks suspicious. Web Shield explores local analysis, plain-language explanations, privacy, and informed choices.',bullets:['Local page and link signals','Human-centered risk communication','Privacy-conscious product design'],url:'https://github.com/AL91Cole/ai-guardian-web-shield',link:'Source & documentation'},
{n:'02',name:'AI Guardian Assistant — Project Labyrinth',type:'DEFENSIVE ZERO TRUST · SIMULATION',text:'How should a system handle an access request with conflicting trust signals? Project Labyrinth models identity-aware decisions, audit trails, and decoy containment.',bullets:['Identity, roles, and least privilege','Access decisions and structured logs','Defensive containment through decoys'],url:'https://github.com/AL91Cole/ai-guardian-assistant-project-labyrinth',link:'Explore Project Labyrinth'},
{n:'03',name:'AI Ethics and Moral Philosophy',type:'ONGOING RESEARCH · RESPONSIBLE AI',text:'An evolving research collection examining how dignity, consent, privacy, accountability, and human responsibility can guide technology decisions. Original frameworks are proposals open to discussion and revision.',bullets:['Ethical reasoning and practical governance','Accessibility and meaningful user choice','Accountability, appeal, and repair'],url:'https://github.com/AL91Cole/ai-ethics-and-moral-philosophy',link:'Read the research'},
{n:'04',name:'Cole Learning Labs',type:'INTERACTIVE EDUCATION · GRADES 7–12',text:'A virtual place to investigate technology problems when classroom hardware cannot be taken apart. Learners work with simulated equipment, settings, artifacts, and security events, then explain how they verified the result.',bullets:['15 investigations across four pathways','Evidence, planning, and verification','Browser-local reports and progress'],url:'#labs',link:'Enter the virtual labs'}
].map(p=>`<article class="project-row"><span class="project-number">${p.n}</span><div><p class="eyebrow">${p.type}</p><h2>${p.name}</h2><p>${p.text}</p><ul class="inline-list">${p.bullets.map(b=>`<li>${b}</li>`).join('')}</ul><a class="text-link" href="${p.url}" ${p.url.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${p.link} ↗</a></div></article>`).join('')}</section>`;}
function about(){return `<section class="wrap page-intro about-intro"><div><p class="eyebrow">ABOUT ALAN “AL” COLE</p><h1>People first.<br><em>Always learning.</em></h1><p>I work as a Computer Technical Assistant at Fonda-Fultonville Central School District while studying cybersecurity at the University at Albany.</p></div><aside class="quote-card"><span aria-hidden="true">“</span><blockquote>I build security systems that think before they trust—and explain before they alarm.</blockquote><p>Alan “Al” Cole</p></aside></section><section class="wrap section split-content"><div><p class="eyebrow">THE WORK BEHIND THE LABS</p><h2>Practical support.<br>Thoughtful security.</h2></div><div><p>Working in K–12 IT keeps my interests grounded in everyday needs: a computer that will not start, a connection that fails, a person who needs a clear explanation.</p><p>My projects connect those experiences with identity and access, defensive engineering, responsible AI, and accessible technology education.</p><p>Cole Learning Labs grew from a classroom question: how can students investigate computer hardware when school devices cannot be taken apart? The virtual bench gives them a place to test ideas and learn from the result.</p></div></section><section class="muted-section"><div class="wrap section split-content"><div><p class="eyebrow">EDUCATION & DIRECTION</p><h2>Building toward<br>what comes next.</h2></div><div class="timeline"><article><span>IN PROGRESS · EXPECTED MAY 2027</span><h3>B.S. in Cybersecurity</h3><p>University at Albany (SUNY)<br>Self-designed concentration: AI-Driven Cybersecurity & Ethical Hacking<br>Minor: AI Ethics & Philosophy</p></article><article><span>PROFESSIONAL LEARNING</span><h3>Credentials & hands-on practice</h3><ul><li>Google Cybersecurity Professional Certificate</li><li>CompTIA Security+</li><li>TryHackMe Cyber Security 101 learning path completed</li><li>Professional Certificate in Computer Systems and Networks — American Public University</li></ul></article><article><span>FUTURE GOAL</span><h3>Computer Technology through CTE</h3><p>I am pursuing the path toward Career and Technical Education certification and developing these learning resources along the way.</p></article></div></div></section><section class="wrap section"><p class="eyebrow">AREAS OF FOCUS</p><div class="focus-grid"><article><h3>Systems & support</h3><p>Windows and Linux, endpoint troubleshooting, networking fundamentals, user support, and clear documentation.</p></article><article><h3>Defensive security</h3><p>Zero Trust, identity and access decisions, least privilege, event analysis, and privacy-conscious design.</p></article><article><h3>Development & ethics</h3><p>JavaScript, React, Next.js, Tailwind CSS, SQLite, and continuing Python and PowerShell fundamentals. Human responsibility stays central.</p></article></div><p class="quiet-note">I also founded CTRL+J Juice Lounge & IT Hub™ LLC, a community technology venture whose active development is currently on hold while I focus on education and career goals.</p></section>`;}

function library(){const completed=countComplete();return `<section class="lab-library-intro"><div class="wrap"><p class="eyebrow">THE VIRTUAL LAB</p><h1>Pull up a chair.<br><em>Work the problem.</em></h1><p>Choose an investigation. Inspect the equipment, follow the evidence, and explain the result.</p><div class="library-meta">${tag('Grades 7–12')}${tag('Browser-based simulations')}${tag(`${completed} of 15 delivered`)}</div></div></section><section class="wrap library-section"><div class="library-toolbar"><div class="track-filters" role="group" aria-label="Filter by pathway"><button data-track="all" class="${libraryTrack==='all'?'active':''}" aria-pressed="${libraryTrack==='all'}">All pathways</button>${Object.entries(tracks).map(([id,t])=>`<button data-track="${id}" class="${libraryTrack===id?'active':''}" aria-pressed="${libraryTrack===id}">${t.short}</button>`).join('')}</div><div class="library-options"><label>Grade band<select id="grade-filter"><option value="all">All grades</option>${['7–8','9–10','11–12'].map(g=>`<option value="${g}" ${libraryGrade===g?'selected':''}>Grades ${g}</option>`).join('')}</select></label><label>Find a lab<input id="lab-search" type="search" value="${esc(libraryQuery)}" placeholder="Search title or ticket…"></label></div></div><p id="lab-count" class="result-count" aria-live="polite"></p><div class="lab-card-grid" id="lab-results"></div><div class="library-guidance"><span class="pathway-symbol">?</span><div><h2>First time at the bench?</h2><p>The Student Guide explains the workflow. Private sessions keep work on this page. Device saving is an explicit choice; export a report when you finish.</p></div>${routeLink('guide','Read the student guide →','button button-outline')}</div></section>`;}
function labCards(){const result=SCENARIOS.filter(s=>(libraryTrack==='all'||s.track===libraryTrack)&&(libraryGrade==='all'||s.grade===libraryGrade)&&`${s.id} ${s.title} ${s.summary}`.toLowerCase().includes(libraryQuery.toLowerCase()));$('#lab-count').textContent=`${result.length} investigation${result.length===1?'':'s'} · ${countComplete()} delivered on this browser`;
$('#lab-results').innerHTML=result.length?result.map(s=>`<a class="lab-card ${tracks[s.track].color}" href="#lab/${s.id}"><div class="lab-card-visual track-${s.track}"><span class="lab-card-code">${s.id}</span><span class="lab-visual-icon">${tracks[s.track].symbol}</span><span class="lab-card-status">${store.labs[s.id]?.closed?'✓ Delivered':store.labs[s.id]?'In progress':'Ready to investigate'}</span></div><div class="lab-card-copy"><p class="eyebrow">${tracks[s.track].short} · GRADES ${s.grade}</p><h2>${s.title}</h2><p>${s.summary}</p><div class="lab-card-foot"><span>${s.minutes} min suggested</span><span>Open bench ↗</span></div></div></a>`).join(''):`<div class="empty-state"><h2>No labs match those filters.</h2><p>Choose another pathway or grade band, or clear your search.</p><button class="button button-outline" id="clear-filters">Clear filters</button></div>`;$('#clear-filters')?.addEventListener('click',()=>{libraryTrack='all';libraryGrade='all';libraryQuery='';history.replaceState(null,'','#labs');renderRoute();});}

function labPage(s){
  const r=recordFor(s);currentLab=s;
  return [
    '<section class="lab-shell single-page-lab"><div class="lab-topbar"><a href="#labs" class="back-link">← All labs</a><div><span class="eyebrow">'+esc(s.id)+' / '+esc(tracks[s.track].name)+'</span><h1>'+esc(s.title)+'</h1></div><span class="tag">GRADES '+esc(s.grade)+'</span><div class="lab-tools"><button id="reading-toggle" class="lab-tool" aria-pressed="false">Larger text</button><button id="saving-options" class="lab-tool">Saving & privacy</button><button id="report-button" class="lab-tool">My report ↗</button></div></div>',
    '<div class="lab-objective"><strong>Your goal</strong><p>'+esc(s.goal)+'</p></div>',
    "<nav class=\"lab-section-nav lab-section-jumps\" aria-label=\"Jump to a lab section\"><button data-lab-section=\"1\" aria-controls=\"lab-problem\"><span class=\"step-number\">1</span>Request & clues<span class=\"section-done\" aria-hidden=\"true\"></span></button><button data-lab-section=\"2\" aria-controls=\"lab-workbench\"><span class=\"step-number\">2</span>Workbench<span class=\"section-done\" aria-hidden=\"true\"></span></button><button data-lab-section=\"3\" aria-controls=\"lab-finish\"><span class=\"step-number\">3</span>Check & finish<span class=\"section-done\" aria-hidden=\"true\"></span></button></nav>",
    "<div class=\"lab-quick-start\" role=\"note\"><h2>How to use this lab</h2><ol><li><strong>Read & collect.</strong> Read the request, choose questions and clues, and write your first idea.</li><li><strong>Try & test.</strong> Use the workbench instructions below. Make one change and read the result.</li><li><strong>Check & explain.</strong> Check the original task, write what happened, and open your report.</li></ol><p class=\"lab-page-help\">Everything is on this page. Scroll normally, or use the numbered shortcuts above. They keep all sections visible and preserve your work.</p><p class=\"lab-session-note\">Private practice: export before leaving. Device saving is optional. Keep names, emails, student IDs, and passwords out of your work.</p></div>",
    '<div id="classroom-status"></div><div class="lab-grid">',
    '<aside id="lab-problem" class="case-sidebar" tabindex="-1" aria-label="1. Request and clues"><section class="case-panel"><h2>1. Read the request</h2><p class="eyebrow">THE SUPPORT REQUEST</p><h2>'+esc(s.requester)+'</h2><blockquote>'+esc(s.brief)+'</blockquote></section>',
    '<section class="case-panel"><h2>Ask a question</h2><p class="panel-help">Choose a question to read the answer. You can try each one.</p><div class="intake-questions">'+s.questions.map((q,i)=>'<button data-question="'+i+'" class="question-button" aria-pressed="'+String(r.questions.includes(i))+'">'+esc(q.label)+' <span>'+ (r.questions.includes(i)?'Read':'+')+'</span></button>').join('')+'</div><div id="question-response" class="question-response" aria-live="polite"></div></section>',
    '<section class="case-panel"><h2>Collect at least two clues</h2><p class="panel-help">Choose a clue to read it. It is added to your notes automatically.</p><div class="clue-buttons">'+s.clues.map(c=>'<button data-clue="'+esc(c.id)+'" class="question-button '+(r.evidence.includes(c.id)?'logged':'')+'" aria-pressed="'+String(r.evidence.includes(c.id))+'">'+esc(c.label)+' <span>'+(r.evidence.includes(c.id)?'Added':'+')+'</span></button>').join('')+'</div><div id="evidence-detail" class="question-response" aria-live="polite"></div></section>',
    '<section class="case-panel guide-plan"><h2>Write your first idea</h2><label class="lab-field">What do you think is causing the problem?<textarea id="plan" maxlength="2000" rows="3" placeholder="I think… because the clues show…">'+esc(r.plan)+'</textarea></label><p class="panel-help">A sentence is enough to begin. You can change your idea as you learn.</p><div class="lab-step-actions"><button class="button" data-jump-section="2">Go to the workbench ↓</button></div></section></aside>',
    '<div id="lab-workbench" class="bench-column" tabindex="-1" role="region" aria-label="2. Workbench"><h2 class="lab-section-heading">2. Use the workbench</h2><div class="bench-label"><span><i class="status-dot"></i> YOUR PRACTICE WORKSPACE</span><span>VIRTUAL ONLY</span></div><div id="workspace" class="workspace"></div><div id="action-feedback" class="action-feedback" role="status">'+esc(r.events.length?r.events.at(-1).message:'Use the controls in the workspace. Make one change, then check what happens.')+'</div><details class="case-panel bench-log"><summary class="panel-title"><strong>What I tried · action log</strong><span id="action-count">'+r.events.length+' actions</span></summary><ol id="bench-log">'+eventList(r)+'</ol></details><div class="lab-step-actions"><button class="lab-tool" data-jump-section="1">↑ Request & clues</button><button class="button" data-jump-section="3">Go to notes & finish ↓</button></div></div>',
    '<aside id="lab-finish" class="evidence-sidebar" tabindex="-1" aria-label="3. Check and finish"><h2 class="lab-section-heading">3. Check & explain</h2><section class="case-panel"><div class="panel-title"><h2>Explain what you tried</h2><span id="clue-count">'+r.evidence.length+' clues</span></div><section class="collected-clues"><h3>Your collected clues</h3><div class="evidence-list" id="evidence-list">'+evidenceList(s,r)+'</div></section><label class="lab-field">What did you try, and what happened?<textarea id="notes" maxlength="4000" rows="4" placeholder="I tried… The result was…">'+esc(r.notes)+'</textarea></label><label class="lab-field">What did you learn?<textarea id="reflection" maxlength="2000" rows="3" placeholder="The evidence showed… Next time I would…">'+esc(r.reflection)+'</textarea></label><p class="panel-help">Use your own words. Write a sentence for each answer.</p></section>',
    '<section class="case-panel verification-panel"><p class="eyebrow">CHECK THE GOAL</p><h2>Does the requested task work?</h2><p>'+esc(s.goal)+'</p><button class="button" id="verify-task">Check the original task</button><div class="verify-result" id="verify-result" role="status">'+(r.verified?'✓ The original task works.':'')+'</div><h3>Before you finish</h3><ul class="lab-finish-checklist"><li data-finish-check="clues">Collect two clues <span></span></li><li data-finish-check="plan">Explain your first idea <span></span></li><li data-finish-check="notes">Describe what you tried <span></span></li><li data-finish-check="reflection">Explain what you learned <span></span></li><li data-finish-check="verified">Check the original task <span></span></li></ul><button class="button" id="close-ticket">Finish investigation & open report</button><button class="button button-outline" id="finish-report">Preview my report</button><p class="save-status">'+esc(workStatus(r,workStorage))+'</p><div class="lab-step-actions"><button class="lab-tool" data-jump-section="2">↑ Workbench</button></div><button class="text-button" id="reset-ticket">Start this lab again</button><div id="reset-confirm" hidden><p>This clears this lab’s current work and any saved copy when device saving is on. Export first.</p><button id="confirm-reset" class="lab-tool">Start over</button> <button id="cancel-reset" class="lab-tool">Keep my work</button></div></section></aside></div>',
    "<div id=\"work-privacy\"></div><div class=\"lab-general-help\"><p><strong>Keyboard:</strong> use Tab to move between controls and Enter or Space to choose a button. The numbered shortcuts scroll to sections on this page.</p><p>Only virtual equipment and fictional information are used. Your real device is never changed. Open My report to review and export your investigation through your teacher’s approved process.</p></div></section>",
    '<dialog id="lab-dialog"><div id="dialog-content"></div><button id="dialog-close" class="button button-outline">Close</button></dialog>'
  ].join('');
}
function evidenceList(s,r){return r.evidence.length?`<ul>${r.evidence.map(id=>`<li>${esc(s.clues.find(c=>c.id===id)?.text||'Clue recorded')}</li>`).join('')}</ul>`:'<p class="panel-help">No clues recorded yet. Inspect a clue to add it here.</p>';}
function eventList(r){return r.events.length?r.events.slice(-10).map(e=>`<li><time>${new Date(e.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time><span>${esc(e.message)}</span></li>`).join(''):'<li class="empty-log">No tests or component changes yet.</li>';}
function bindLab(s){
  bindWorkPrivacy(s);
  const r=recordFor(s),workspace=$('#workspace'),shell=$('.lab-shell');
  const panels=[$('.case-sidebar'),$('.bench-column'),$('.evidence-sidebar')];
  const renderBench=()=>s.track==='hardware'?renderHardware(workspace,s.id,r.state,action):renderWorkspace(workspace,s,r.state,action);
  function jumpToSection(section,moveFocus=true){
    const requested=Number(section);
    const index=Number.isInteger(requested)?Math.max(1,Math.min(3,requested))-1:0;
    $$('[data-lab-section]').forEach(button=>button.setAttribute('aria-current',Number(button.dataset.labSection)===index+1?'location':'false'));
    if(moveFocus){const panel=panels[index];panel.focus({preventScroll:true});panel.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
  }
  function refreshStatus(){
    const checks={clues:r.evidence.length>=2,plan:r.plan.trim().length>=12,notes:r.notes.trim().length>=15,reflection:r.reflection.trim().length>=15,verified:r.verified===true};
    const done=[checks.clues&&checks.plan,r.verified,r.closed];
    $$('[data-lab-section]').forEach((button,index)=>{button.classList.toggle('is-complete',done[index]);button.querySelector('.section-done').textContent=done[index]?'✓':'';});
    $$('[data-finish-check]').forEach(item=>{const complete=checks[item.dataset.finishCheck]===true;item.classList.toggle('is-complete',complete);item.querySelector('span').textContent=complete?'Done':'To do';});
    $('.save-status').textContent=workStatus(r,workStorage);$('#action-count').textContent=r.events.length+' actions';
  }
  function action(id,value){
    const result=s.track==='hardware'?applyHardwareAction(s.id,r.state,id):applyWorkspaceAction(s.id,r.state,id,value);
    r.state=result.state;
    const inspectOnly=s.track==='hardware'&&(id.startsWith('inspect-')||id.startsWith('view-'));
    if(!inspectOnly){r.verified=false;r.closed=false;$('#verify-result').textContent='';}
    r.events.push({time:new Date().toISOString(),message:result.message,kind:result.kind});
    save();renderBench();$('#action-feedback').textContent=result.message;$('#action-feedback').dataset.kind=result.kind;$('#bench-log').innerHTML=eventList(r);refreshStatus();
  }
  renderBench();
  $$('[data-question]').forEach(button=>button.addEventListener('click',()=>{const i=Number(button.dataset.question);if(!r.questions.includes(i))r.questions.push(i);button.setAttribute('aria-pressed','true');button.querySelector('span').textContent='Read';$('#question-response').textContent=s.questions[i].answer;save();}));
  $$('[data-clue]').forEach(button=>button.addEventListener('click',()=>{const clue=s.clues.find(c=>c.id===button.dataset.clue);if(!r.evidence.includes(clue.id))r.evidence.push(clue.id);button.classList.add('logged');button.setAttribute('aria-pressed','true');button.querySelector('span').textContent='Added';$('#evidence-detail').textContent=clue.text;$('#evidence-list').innerHTML=evidenceList(s,r);$('#clue-count').textContent=r.evidence.length+' clues';save();refreshStatus();}));
  ['plan','notes','reflection'].forEach(field=>$('#'+field).addEventListener('input',event=>{r[field]=event.target.value;r.closed=false;save();refreshStatus();}));
  $('#verify-task').addEventListener('click',()=>{const result=s.track==='hardware'?verifyHardware(s.id,r.state):verifyWorkspace(s.id,r.state);r.verified=result.ok;r.closed=r.closed&&result.ok;r.events.push({time:new Date().toISOString(),message:'Verification: '+result.message,kind:result.ok?'success':'warning'});$('#verify-result').textContent=(result.ok?'✓ ':'Try again: ')+result.message;$('#bench-log').innerHTML=eventList(r);save();refreshStatus();});
  $('#close-ticket').addEventListener('click',()=>{
    const check=s.track==='hardware'?verifyHardware(s.id,r.state):verifyWorkspace(s.id,r.state);
    if(!check.ok){$('#verify-result').textContent='The task is not ready yet. '+check.message+' Return to the workbench to keep trying.';return;}
    if(r.evidence.length<2||r.plan.trim().length<12){jumpToSection(1,true);showNotice('Collect at least two clues and write a sentence explaining your first idea. Your work is still here.');return;}
    if(r.notes.trim().length<15||r.reflection.trim().length<15){$('#verify-result').textContent='Write a sentence about what you tried and a sentence about what you learned. Then finish your investigation.';$('#notes').focus();return;}
    r.verified=true;r.closed=true;save();refreshStatus();showNotice('Investigation finished. Review your report before exporting.');openReport(s,r);
  });
  $('#reading-toggle').addEventListener('click',event=>{const on=shell.classList.toggle('larger-reading');event.target.setAttribute('aria-pressed',String(on));});
  $$('[data-lab-section]').forEach(button=>button.addEventListener('click',()=>jumpToSection(button.dataset.labSection,true)));
  $$('[data-jump-section]').forEach(button=>button.addEventListener('click',()=>jumpToSection(button.dataset.jumpSection,true)));
  $('#saving-options').addEventListener('click',()=>{const options=$('#work-privacy details');options.open=true;options.querySelector('summary').focus({preventScroll:true});options.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});
  $('#report-button').addEventListener('click',()=>openReport(s,r));$('#finish-report').addEventListener('click',()=>openReport(s,r));
  $('#reset-ticket').addEventListener('click',()=>{$('#reset-confirm').hidden=false;});$('#cancel-reset').addEventListener('click',()=>{$('#reset-confirm').hidden=true;});
  $('#confirm-reset').addEventListener('click',()=>{delete store.labs[s.id];save();renderRoute();});
  $('#dialog-close').addEventListener('click',()=>$('#lab-dialog').close());refreshStatus();
  classroomConnection=classroomSharingPaused?null:attachClassroomLab({scenarioId:s.id,record:r,storageKey,onRestore:work=>{store.labs[s.id]=normalizeLabRecord(s,work);save();renderRoute();}});
}
function reportText(s,r){return `COLE LEARNING LABS — INVESTIGATION REPORT\n${s.id} · ${s.title}\nGrades ${s.grade} · ${tracks[s.track].name}\nStatus: ${r.closed?'DELIVERED':r.verified?'TECHNICALLY VERIFIED — TICKET OPEN':'IN PROGRESS'}\n\nORIGINAL TASK\n${s.goal}\n\nEVIDENCE\n${r.evidence.map(id=>'- '+(s.clues.find(c=>c.id===id)?.text||id)).join('\n')||'No evidence recorded.'}\n\nWORKING EXPLANATION\n${r.plan||'Not recorded.'}\n\nTEST NOTES\n${r.notes||'Not recorded.'}\n\nACTION LOG\n${r.events.map(e=>'- '+e.message).join('\n')||'No actions recorded.'}\n\nREFLECTION\n${r.reflection||'Not recorded.'}\n\nThis is a simulated learning activity. Private-session work stays on this page unless exported or explicitly saved on this device. If you explicitly join an enabled classroom, assigned lab drafts and submitted snapshots may be shared with that teacher. Technical progress is student-reported; teachers review and grade submissions.\n`;}
function openReport(s,r){
  reportCleanup?.();
  const content=reportText(s,r),panel=$('#dialog-content'),dialog=$('#lab-dialog');
  panel.innerHTML=[
    '<p class="eyebrow">STUDENT REPORT</p><h2>'+esc(s.id)+' · '+esc(s.title)+'</h2>',
    '<p>Review your notes for names, emails, student IDs, passwords, and private school details. Close this report and edit your lab notes to remove them before exporting. This tool does not automatically detect personal information.</p>',
    '<label class="lab-field">Review your report<textarea id="report-text" rows="10" readonly>'+esc(content)+'</textarea></label>',
    '<section class="report-encryption"><h3>Encrypt for your teacher</h3><p>Use a public key supplied through your teacher’s trusted school channel. Anyone with its matching private key and passphrase can decrypt this report. Encryption does not verify who wrote it.</p>',
    '<label class="lab-field">Teacher public key (.cllpub)<input id="report-public-key" type="file" accept=".cllpub"></label>',
    '<p class="report-fingerprint" id="report-fingerprint">No public key selected.</p>',
    '<label class="privacy-checkbox"><input id="report-key-confirm" type="checkbox" disabled><span>I compared this fingerprint with the one supplied by my teacher through a trusted school channel.</span></label>',
    '<div class="button-row"><button class="button" id="encrypt-report" disabled>Encrypt this report</button><a class="button button-outline" id="encrypted-report-download" download="cole-lab-report.cllreport" hidden>Download encrypted report</a></div>',
    '<p role="status" id="report-encryption-status"></p><p><a href="secure-reports.html" target="_blank" rel="noopener noreferrer">Teacher key setup and report reader ↗</a>. Submit the downloaded file through your school’s approved process. This does not connect to Google Classroom. Your school’s submission system can still show your account identity and attachment metadata to authorized people.</p></section>',
    '<details class="report-plain"><summary>Plain-text export</summary><p>A plain-text copy can be read by anyone who can access it. Use only your teacher’s approved submission process.</p>',
    '<label class="privacy-checkbox"><input id="plain-report-confirm" type="checkbox"><span>I reviewed the report for private information and have approval to export an unencrypted copy.</span></label>',
    '<div class="button-row"><button class="button button-outline" id="copy-report" disabled>Copy plain-text report</button><a class="button button-outline" id="download-report" download="cole-learning-lab-report.txt" aria-disabled="true">Download plain text</a></div></details>'
  ].join('');
  let active=true,selection=0,publicFile='';
  const urls=new Set(),keyInput=$('#report-public-key'),confirm=$('#report-key-confirm'),encrypt=$('#encrypt-report'),encrypted=$('#encrypted-report-download'),status=$('#report-encryption-status'),fingerprint=$('#report-fingerprint'),plain=$('#plain-report-confirm'),plainLink=$('#download-report'),copy=$('#copy-report');
  const current=token=>active&&dialog.open&&panel.isConnected&&selection===token;
  function revokeLinks(){for(const url of urls)URL.revokeObjectURL(url);urls.clear();encrypted.hidden=true;encrypted.removeAttribute('href');plain.checked=false;plainLink.removeAttribute('href');plainLink.setAttribute('aria-disabled','true');copy.disabled=true;}
  function cleanup(){if(!active)return;active=false;selection++;publicFile='';revokeLinks();panel.replaceChildren();dialog.removeEventListener('close',cleanup);if(reportCleanup===cleanup)reportCleanup=null;}
  reportCleanup=cleanup;dialog.addEventListener('close',cleanup);
  keyInput.addEventListener('change',async()=>{
    const token=++selection;publicFile='';confirm.checked=false;confirm.disabled=true;encrypt.disabled=true;fingerprint.textContent='Checking public key…';status.textContent='';revokeLinks();
    try{
      const file=keyInput.files?.[0];
      if(!file||!file.name.toLowerCase().endsWith('.cllpub')||file.size<1||file.size>16000)throw new Error('Invalid file.');
      const text=await file.text(),cryptoModule=await import('./report-crypto.js?release=20261016-single-page4');
      const result=await cryptoModule.inspectPublicKey(text);
      if(!current(token))return;
      publicFile=text;fingerprint.textContent=result.fingerprint;confirm.disabled=false;
    }catch{if(current(token)){fingerprint.textContent='Public key could not be read. Use the .cllpub file supplied by your teacher.';}}
  });
  confirm.addEventListener('change',()=>{encrypt.disabled=!confirm.checked||!publicFile;});
  encrypt.addEventListener('click',async()=>{
    if(!confirm.checked||!publicFile)return;
    const token=selection,key=publicFile;
    encrypt.disabled=true;keyInput.disabled=true;confirm.disabled=true;encrypted.hidden=true;status.textContent='Encrypting on this device…';
    try{
      const cryptoModule=await import('./report-crypto.js?release=20261016-single-page4');
      const protectedReport=await cryptoModule.encryptReport(key,{report:content,alias:cryptoModule.generateAlias()});
      if(!current(token))return;
      const url=URL.createObjectURL(new Blob([protectedReport],{type:'application/octet-stream'}));urls.add(url);encrypted.href=url;encrypted.hidden=false;
      status.textContent='Encrypted report ready. Only holders of the matching private key and passphrase can open its contents. Upload through your school’s approved process.';
    }catch{if(current(token))status.textContent='The report could not be encrypted. Check the teacher key and use a current browser over HTTPS.';}
    finally{if(current(token)){keyInput.disabled=false;confirm.disabled=false;encrypt.disabled=!confirm.checked;}}
  });
  plain.addEventListener('change',()=>{
    copy.disabled=!plain.checked;
    if(plain.checked){const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));urls.add(url);plainLink.href=url;plainLink.removeAttribute('aria-disabled');}
    else{const url=plainLink.getAttribute('href');if(url){URL.revokeObjectURL(url);urls.delete(url);}plainLink.removeAttribute('href');plainLink.setAttribute('aria-disabled','true');}
  });
  plainLink.addEventListener('click',event=>{if(!plain.checked)event.preventDefault();});
  copy.addEventListener('click',async()=>{if(!plain.checked)return;try{await navigator.clipboard.writeText(content);if(active)showNotice('Plain-text report copied. Clear the clipboard before sharing this device.');}catch{if(active){$('#report-text').select();showNotice('Select Copy from your browser, or use the approved download.');}}});
  dialog.showModal();
}

function educators(){return `<section class="wrap page-intro"><p class="eyebrow">FOR EDUCATORS</p><h1>Teach the process.<br><em>Make thinking visible.</em></h1><p>Use the virtual labs for demonstrations, guided investigations, independent practice, and reflection. Adapt each activity to your learners and lesson objectives.</p></section><section class="wrap section split-content"><div><h2>A lesson you can build on.</h2><p>The suggested routine works across all four pathways. Timings are starting points, not requirements.</p>${routeLink('labs','Choose an investigation ↗')}</div><ol class="lesson-timeline"><li><span>01 / BEFORE CLASS</span><h3>Preview the environment</h3><p>Complete the lab yourself. Check the grade band, original task, available controls, and the student instructions. Keep your grading materials in your school’s private teacher resources.</p></li><li><span>02 / 5–10 MINUTES</span><h3>Model the first questions</h3><p>What does the user need? What changed? Which observations would help distinguish likely causes?</p></li><li><span>03 / 15–30 MINUTES</span><h3>Let students investigate</h3><p>Use pairs or independent practice. Require a reason for each test, and a note about the result.</p></li><li><span>04 / 5–10 MINUTES</span><h3>Verify, explain, and debrief</h3><p>Check the original task. Compare approaches, then copy or download a report for your approved submission system.</p></li></ol></section><section class="muted-section"><div class="wrap section">${sectionHead('DIFFERENT STARTING POINTS','Three grade bands. Room to grow.')}<div class="focus-grid"><article><span class="grade-number">7–8</span><h3>Foundations & safety</h3><p>Begin with visible hardware symptoms, privacy-aware prompts, and phishing triage. Model vocabulary and one change at a time.</p></article><article><span class="grade-number">9–10</span><h3>Systems & evidence</h3><p>Connect addresses, access settings, AI claims, and security events with the evidence needed to explain a decision.</p></article><article><span class="grade-number">11–12</span><h3>Audit & remediation</h3><p>Investigate startup services, review generated code, and patch an authorized simulated access-control weakness.</p></article></div></div></section><section class="wrap section prose"><h2>Assess more than a correct answer.</h2><p>Review observations, a justified plan, safe actions, verification, and communication. The public labs do not include teacher grading criteria. Keep assessment rubrics and answer keys in your school’s authenticated teacher resources. The report captures the student’s own explanation and action log.</p><h2>Support different learners.</h2><p>Use the larger-text control, a keyboard or click alternative to dragging, paired investigation, extra time, or an oral explanation. Each lab keeps the request, workbench, notes, and finish controls visible on one page. Short instructions stay beside the controls. The numbered shortcuts scroll to a section without hiding another section or resetting work. The component selector and Install buttons work with touch, a trackpad, or a keyboard.</p><h2>Plan for saved work.</h2><p>Independent labs keep work on the current page by default. Device saving requires an explicit choice. Teachers can supply a public encryption key so students can download encrypted reports and manually submit them through an approved learning system. No Classroom roster or automatic grade synchronization is connected. An optional connected classroom adds assigned drafts, teacher review, and submitted snapshots only after explicit enrollment; it requires a configured teacher login and storage service.</p><h2>Connect cybersecurity to responsibility.</h2><p>All security investigations use fictional artifacts and simulated systems. Discuss authorization, scope, least privilege, remediation, and responsible reporting alongside the technical work.</p><h2>Two ways to use the labs</h2><p><a href="classroom.html">Explore classroom options and a fictional teacher demo</a>. Real classroom enrollment is locked during privacy and school approval review. A teacher email or hosting setting cannot unlock record collection. The demo does not contain real students or save grades to a server.</p><h2>School technology review</h2><p><a href="school-it.html">Share the School IT review page</a> for privacy details, browser requirements, and GoGuardian category or allow-list review. School filtering policies still control access.</p><h2>Teaching purpose</h2><p>Created by Mx. Cole toward a future goal of teaching Computer Technology through CTE. These activities are adaptable learning resources; educators select the objectives and assessment approach for their own classes.</p></section>`;}
function guide(){return '<section class="wrap page-intro"><p class="eyebrow">STUDENT GUIDE</p><h1>One page.<br><em>Everything you need.</em></h1><p>You do not need to know the answer before you begin. The request, workbench, notes, and finish controls stay together, with short instructions next to the tools.</p></section><section class="wrap section guide-layout"><aside><h2>Ready to begin?</h2><p>Choose a lab, read the goal, and follow the numbered steps.</p>'+routeLink('labs','Choose a lab ↗')+'</aside><div class="prose"><h2>1. Understand the problem</h2><p>Read the request. Choose the question and clue buttons to learn more. Collect at least two clues and write a sentence about what you think is happening.</p><h2>2. Use the workbench</h2><p>Scroll to the workbench or choose its numbered shortcut. Read its short instructions, try one change at a time, and use the Test or Check button to see what happened. Hardware parts can be clicked, tapped, or selected with the keyboard.</p><h2>3. Check &amp; finish</h2><p>Scroll to Check & finish or choose its numbered shortcut. Check the original task, explain what you tried and learned, then use Finish investigation &amp; open report. Review your report before exporting through your teacher’s approved process.</p><h2>Need to go back?</h2><p>Scroll to any section or use the numbered shortcuts. Every section stays visible and your work stays on this page. The workbench instructions are always visible beside its controls. Larger text makes the instructions easier to read.</p><h2>Before leaving</h2><p>Private sessions do not automatically save your work. Open My report to export it, or use Saving &amp; privacy to choose device saving on an approved personal browser profile. Device-saved work is not encrypted; clear it before sharing the profile. Do not enter names, emails, student IDs, passwords, or private school details.</p><h2>Keep it virtual</h2><p>Use only the simulated equipment and fictional information in the lab. Ethical cybersecurity activities require the on-screen scope agreement. Never test a real person’s account, device, network, or website without authorization.</p></div></section>';}
function connect(){return `<section class="wrap page-intro"><p class="eyebrow">LET’S CONNECT</p><h1>Good technology<br><em>starts with people.</em></h1><p>For professional opportunities, project conversations, or ideas for technology education, connect with me on LinkedIn.</p>${routeLink('about','About my background →','text-link')}</section><section class="wrap connect-grid section">${[{name:'LinkedIn',type:'PROFESSIONAL CONNECTIONS',copy:'Connect with Alan “Al” Cole.',url:'https://www.linkedin.com/in/alan91cole'},{name:'GitHub',type:'SOURCE & PROJECTS',copy:'Explore code, documentation, and research.',url:'https://github.com/AL91Cole'},{name:'Credly',type:'CREDENTIALS',copy:'View my public credentials and achievements.',url:'https://www.credly.com/users/alan91cole'},{name:'TryHackMe',type:'CONTINUING LEARNING',copy:'Visit my cybersecurity learning profile.',url:'https://tryhackme.com/p/Alan91Cole'}].map(p=>`<a href="${p.url}" target="_blank" rel="noopener noreferrer"><p class="eyebrow">${p.type}</p><h2>${p.name} ↗</h2><p>${p.copy}</p></a>`).join('')}</section>`;}
function privacy(){return privacyPage();}

function renderRoute(){reportCleanup?.();reportCleanup=null;classroomConnection?.dispose();classroomConnection=null;currentLab=null;document.body.classList.remove('lab-view');const parts=(location.hash.slice(1)||'home').split('/');let [page,id]=parts;let html,title;if(page==='lab'){const s=SCENARIOS.find(x=>x.id===id);if(s){document.body.classList.add('lab-view');html=labPage(s);title=`${s.id} · ${s.title}`;}else{html=`<section class="wrap page-intro"><h1>That ticket is not on this bench.</h1><p>Choose one of the available investigations.</p>${routeLink('labs','All virtual labs →')}</section>`;title='Lab not found';}}else{const pages={home:[home,'Alan Cole'],projects:[projectPage,'Projects'],about:[about,'About Alan Cole'],labs:[library,'Virtual labs'],educators:[educators,'For educators'],guide:[guide,'Student guide'],connect:[connect,'Connect'],privacy:[privacy,'Privacy & accessibility']};if(!Object.hasOwn(pages,page))page='home';if(page==='labs'&&Object.hasOwn(tracks,id))libraryTrack=id;[html,title]=[pages[page][0](),pages[page][1]];}
$('#main').innerHTML=html;document.title=`${title} · Cole Learning Labs`;$$('#site-nav a').forEach(a=>{const active=a.hash===`#${page==='lab'?'labs':page}`;if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#site-nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');
if(page==='labs'){labCards();$$('[data-track]').forEach(b=>b.addEventListener('click',()=>{libraryTrack=b.dataset.track;history.replaceState(null,'','#labs');renderRoute();}));$('#grade-filter').addEventListener('change',e=>{libraryGrade=e.target.value;labCards();});$('#lab-search').addEventListener('input',e=>{libraryQuery=e.target.value;labCards();});}if(currentLab)bindLab(currentLab);window.scrollTo(0,0);}
$('#menu-toggle').addEventListener('click',()=>{const on=$('#site-nav').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(on));});
$('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});});
window.addEventListener('hashchange',()=>{renderRoute();$('#main').focus({preventScroll:true});});
renderRoute();
